RESET_REASON = 'Explicit posting introduced: not public until the BAC posts it.'


def move_legacy_stamps_to_history(apps, schema_editor):
    """PRs start unposted. An old automatic posting stamp is kept as history
    (a "posted" row at its time, then an "unposted" row now) instead of making
    the PR public without a deliberate BAC decision."""
    PurchaseRequest = apps.get_model('api', 'PurchaseRequest')
    PRPostingLog = apps.get_model('api', 'PRPostingLog')
    now = timezone.now()
    for pr in PurchaseRequest.objects.exclude(posted_at__isnull=True):
        PRPostingLog.objects.create(
            pr=pr, action='posted', automatic=True, reason=LEGACY_STAMP_REASON,
            changed_by_username=pr.posted_by or '', changed_at=pr.posted_at,
        )
        PRPostingLog.objects.create(
            pr=pr, action='unposted', automatic=True, reason=RESET_REASON, changed_at=now,
        )
    PurchaseRequest.objects.exclude(posted_at__isnull=True).update(posted_at=None, posted_by='', is_posted=False)


